import{_ as o,o as t,c as r,a3 as d}from"./chunks/framework.b3pIO3is.js";const g=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),n={name:"explanation/concepts.md"};function i(a,e,s,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>pavo&#39;s vocabulary is the wire contract made human: a <strong>driver</strong> ships <strong>views</strong>, a <strong>host</strong> interprets them, and everything in between is a <strong>node</strong> in a declarative tree.</p><h2 id="wire-entities" tabindex="-1">Wire entities <a class="header-anchor" href="#wire-entities" aria-label="Permalink to &quot;Wire entities&quot;">​</a></h2><ul><li><strong>Driver</strong> — a <code>tamias-driver-&lt;type&gt;</code> executable discovered on <code>PATH</code> or in <code>&lt;tamias-home&gt;/drivers/</code>. Speaks ndjson JSON-RPC over stdio; declares a manifest (routes, views, chrome contributions, deps) and answers ops (<code>view</code>, <code>query</code>, <code>submit</code>, <code>render</code>, <code>jobs</code>, <code>notifications</code>).</li><li><strong>ViewNode IR</strong> — the declarative tree drivers emit: <code>panel</code>, <code>table</code>, <code>tree</code>, <code>graph</code>, <code>form</code>, <code>kv</code>, <code>markdown</code>, <code>embed</code>, <code>row</code>, <code>column</code>, <code>svg</code>, <code>placeholder</code>. Data is <em>not</em> embedded — nodes name <code>query</code> bindings the host resolves.</li><li><strong>QueryBinding</strong> — <code>{op, params?, driver?}</code>: which wire op fetches a node&#39;s data. <code>driver</code> set = cross-driver query into another driver&#39;s <code>serve</code>.</li><li><strong>RenderModel</strong> — the canonical output of a renderer plugin&#39;s <code>render</code> op: resolved nodes + view-model data, surface-agnostic.</li><li><strong>Manifest <code>contributes</code></strong> — eight chrome slots (<code>navbar</code>, <code>dashboard</code>, <code>statusbar</code>, <code>routes</code>, <code>sidebar</code>, <code>headerActions</code>, <code>notifications</code>, <code>jobs</code>) a driver fills to compose the shared screen.</li><li><strong><code>deps</code></strong> — <code>requires</code>/<code>optional</code> driver-name graph; the host topologically sorts and quarantines offenders.</li></ul><h2 id="host-entities" tabindex="-1">Host entities <a class="header-anchor" href="#host-entities" aria-label="Permalink to &quot;Host entities&quot;">​</a></h2><ul><li><strong>View ref</strong> — <code>&lt;driver&gt;:&lt;view&gt;</code>; on the CLI an argument, on the web a <code>/view/...</code> URL — the same link everywhere.</li><li><strong>View-model cache</strong> — host-side TTL cache of resolved binding data; partial degradation per binding.</li><li><strong>Renderer plugin</strong> — a driver that claims view <code>kind</code>s via manifest <code>renderers[]</code> and answers <code>render</code> with a RenderModel; failure falls back to built-in interpretation.</li><li><strong>Surfaces</strong> — the three interpreters of the same IR: CLI (text), TUI (ratatui), web (Nuxt via <code>pavo serve</code> bridge).</li></ul><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to &quot;Invariants&quot;">​</a></h2><ul><li><strong>Additive-only v1</strong> — new optional fields, kinds, ops may appear anytime; existing spellings never change meaning.</li><li><strong>Unknown kinds degrade</strong> — renderers meet an unknown <code>kind</code> as generic KV; <code>props</code> is an open map.</li><li><strong>Drivers stay proxies</strong> — pavo hosts collect <code>form</code> values and display <code>SubmitResult</code>; every mutation semantic belongs to the driver.</li></ul>',8)])])}const v=o(n,[["render",i]]);export{g as __pageData,v as default};
